import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, sin, dot, fract, mul, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();
  root.name = 'editorial-oversized-headline';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'NOVA ATELIER / JOURNAL', role: 'kicker' },
    { text: 'PRECISION IS', role: 'hero' },
    { text: 'A HABIT.', role: 'hero' },
    { text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.', role: 'body' },
    { text: 'ISSUE 12 / JULY 2026', role: 'caption' },
  ];

  const PX_PER_UNIT = 200; // hero fontSize 124px == 0.62 unit em height

  // ---------------------------------------------------------------
  // Backdrop plate: 7 x 5.5 engineered vertical gradient + light grain
  // ---------------------------------------------------------------
  const plateGeo = new PlaneGeometry(7, 5.5, 1, 1);
  const plateMat = new MeshBasicNodeMaterial();

  const topColor = uniform(new Color(colors.background));
  const botColor = uniform(new Color(colors.surface));
  const uvNode = uv();

  const gradient = mix(botColor, topColor, uvNode.y);

  const noiseSeed = dot(mul(uvNode, 1000.0), vec2(12.9898, 78.233));
  const grain = fract(mul(sin(noiseSeed), 43758.5453)).sub(0.5).mul(0.015);

  plateMat.colorNode = gradient.add(vec3(grain, grain, grain));

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);

  // ---------------------------------------------------------------
  // Text blocks
  // ---------------------------------------------------------------
  const findText = (role, idx = 0) => {
    const matches = items.filter((it) => it.role === role);
    return matches[idx]?.text ?? '';
  };

  const kickerText = findText('kicker') || 'NOVA ATELIER / JOURNAL';
  const heroLine1 = items.find((it) => it.role === 'hero' && /precision/i.test(it.text))?.text
    ?? findText('hero', 0) ?? 'PRECISION IS';
  const heroLine2 = items.find((it) => it.role === 'hero' && it.text !== heroLine1)?.text
    ?? findText('hero', 1) ?? 'A HABIT.';
  const bodyText = findText('body') || '';
  const captionText = findText('caption') || '';

  const blocks = [];

  // Kicker
  const kicker = ctx.fontAtlas.createText(kickerText, {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 18 * 0.12,
  });
  kicker.position.set(-3.1, 1.7, 0.01);
  root.add(kicker);
  blocks.push(kicker);

  // Hero shadow (letterpress duplicate, 0.02 units behind, ink color)
  const heroShadow1 = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124,
    color: colors.ink,
    align: 'left',
    letterSpacingPx: 124 * -0.015,
  });
  heroShadow1.position.set(-3.08, 0.88, -0.01);
  root.add(heroShadow1);

  const heroShadow2 = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124,
    color: colors.ink,
    align: 'left',
    letterSpacingPx: 124 * -0.015,
  });
  heroShadow2.position.set(-3.08, 0.23, -0.01);
  root.add(heroShadow2);

  // Hero (front, brightest element — paper on dark stage)
  const hero1 = ctx.fontAtlas.createText(heroLine1, {
    fontSize: 124,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 124 * -0.015,
  });
  hero1.position.set(-3.1, 0.9, 0.02);
  root.add(hero1);
  blocks.push(hero1);

  const hero2 = ctx.fontAtlas.createText(heroLine2, {
    fontSize: 124,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 124 * -0.015,
  });
  hero2.position.set(-3.1, 0.25, 0.02);
  root.add(hero2);
  blocks.push(hero2);

  // Accent underline rule
  const ruleGeo = new PlaneGeometry(2.2, 0.05, 1, 1);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = vec3(uniform(new Color(colors.accent))).mul(1.2);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1 + 2.2 / 2, -0.15, 0.02);
  rule.scale.x = 0.0001;
  root.add(rule);

  // Body paragraph
  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 4.5 * PX_PER_UNIT,
  });
  body.position.set(-3.1, -0.8, 0.01);
  root.add(body);
  blocks.push(body);

  // Caption
  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 18 * 0.08,
  });
  caption.position.set(-3.1, -1.9, 0.01);
  root.add(caption);
  blocks.push(caption);

  // ---------------------------------------------------------------
  // Entrance motion: rise-in per block, top -> bottom, 80ms stagger
  // ---------------------------------------------------------------
  const riseBlocks = [kicker, hero1, hero2, body, caption];
  const shadowMap = new Map([
    [hero1, heroShadow1],
    [hero2, heroShadow2],
  ]);

  const baseY = riseBlocks.map((b) => b.position.y);
  const shadowBaseY = [heroShadow1.position.y, heroShadow2.position.y];

  riseBlocks.forEach((b, i) => {
    b.position.y = baseY[i] + 0.4;
    if (b.material) b.material.transparent = true;
    b.traverse?.((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  });
  heroShadow1.position.y = shadowBaseY[0] + 0.4;
  heroShadow2.position.y = shadowBaseY[1] + 0.4;
  [heroShadow1, heroShadow2].forEach((s) => {
    s.traverse?.((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  });

  const setOpacity = (obj, val) => {
    obj.traverse?.((child) => {
      if (child.material) child.material.opacity = val;
    });
  };

  const tl = gsap.timeline({ delay: 0.05 });

  riseBlocks.forEach((b, i) => {
    const target = { y: b.position.y, o: 0 };
    const finalY = baseY[i];
    const shadow = shadowMap.get(b);

    tl.to(
      b.position,
      { y: finalY, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
    tl.to(
      target,
      {
        o: 1,
        duration: 0.7,
        ease: 'power3.out',
        onUpdate: () => setOpacity(b, target.o),
      },
      i * 0.08
    );

    if (shadow) {
      tl.to(
        shadow.position,
        { y: finalY - 0.02, duration: 0.7, ease: 'power3.out' },
        i * 0.08
      );
      tl.to(
        target,
        {
          onUpdate: () => setOpacity(shadow, target.o),
        },
        i * 0.08
      );
    }
  });

  // Rule draws in after hero lands
  const heroLandTime = 2 * 0.08 + 0.7;
  tl.to(
    rule.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    heroLandTime
  );

  // Idle: gentle breathing on the rule (single slow transform, <=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: heroLandTime + 0.5 });
  idleTl.to(rule.scale, { y: 1.15, duration: 2.4, ease: 'sine.inOut' });

  // ---------------------------------------------------------------
  // Handlers / cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();

    plateGeo.dispose();
    plateMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();

    const disposeObj = (obj) => {
      obj.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    };

    [kicker, hero1, hero2, heroShadow1, heroShadow2, body, caption].forEach(disposeObj);

    root.clear();
  };

  return root;
}
